`timescale 1ns/1ps
// KV-KT-E0 2026-11-18 (FABLE-FIX-KV-HG fix #2): lock-step of the kt-station heads ot_qkh_head_native_r4*_kst (generated by
// tools/qwen_kv_die/head_st_rtl.py) against the heads they are generated from, on every edge.  One build a FORM holds
//   ur = the source head (today)
//   ua = <head>_kst #(.KT_ST(0))   must equal ur on the same edge (every output)
//   ub = <head>_kst #(.KT_ST(2))   sc_d / sc_f / g_f must equal ur 2 edges earlier
//   uc = <head>_kst #(.KT_ST(1))   ... 1 edge earlier
//   um = <head>_kst #(.KT_ST(2),.KT_MUT(1))  lanes 0, 1 WITHOUT stations (the 14-lane parent-only form of the timing proof
//        kit): must NOT follow the 2-edge law (built-in negative control, every run)
// The outputs that do not pass the K-tree (ft_ti_b / ft_e_b / ft_s_b feed-through, nb_d) stay on the same edge in all.
// FORM 0 _s_lk (the head of the bound KV die: K-tree ot_qkh_ktree_lk)   1 _ft_s_lk   2 _s   3 _ft_s   4 r4 (node beat)
// Stimulus: the tb_qkh_head_r4_s K passes (Q beats, then a K row every edge, random e / ft words, rows with FP specials
// for the fault path), seed +SEED, with reset pulses between and INSIDE passes (8 and 4 edges).
// Reset transient: the K-tree data path is not reset, so for TRANS edges after a reset release sc_d carries the tree's
// own reset-aligned values (no valid score: the control tile tags a score SCD edges after its K issue, never here).  They
// leave on the same edge with or without stations, so inside that window sc_d may equal the source head on the same edge
// OR the law (counted, printed); outside it and for sc_f / g_f on EVERY edge the law is exact.
// +RAND=1 with run argument +verilator+rand+reset+2 (build --x-initial unique): every flop powers up random, so sc_d is
// compared once the first reset has flushed the unreset data regs (FLUSH edges); sc_f / g_f are compared from the first
// edge out of reset (a station whose power-up value reached the K-tree fails).
// Negative controls at run time: +SHB=<n> checks ub against the wrong shift n, +CHKM=1 checks um against the law: FAIL.
module tb_qkh_head_kst;
  parameter integer FORM=0;
  localparam integer FLUSH=160,TRANS=96;
  reg ck=0,rst_n=0;always #1 ck=~ck;
  reg [3:0] c_in=0;reg [1023:0] row_in=0;reg [15:0] e_in=0;reg [11:0] lt_in=0;reg [1:0] hid=2'd1;
  reg q_valid_in=0;reg [5:0] q_beat_in=0;reg [511:0] q_data_in=0;
  reg [1558:0] ft_ti_a=0;reg [15:0] ft_e_a=0;reg [33:0] ft_s_a=0;
  wire [33:0] o_r,o_a,o_b,o_c,o_m;           // {g_f, sc_f, sc_d}
  wire [2632:0] u_r,u_a,u_b,u_c,u_m;         // outside the K-tree path: {nb_d 1024, ft_s_b 34, ft_e_b 16, ft_ti_b 1559}
`define KST_COM .ck_front({4{ck}}),.ck_score(ck),.ck_kt(ck),.ck_stin({16{ck}}),.ck_stk({16{ck}}),.ck_lane({16{ck}}),.rst_n(rst_n), \
    .c_in(c_in),.row_in(row_in),.e_in(e_in),.lt_in(lt_in),.hid(hid),.q_valid_in(q_valid_in),.q_beat_in(q_beat_in),.q_data_in(q_data_in)
`define KST_FT(x) .ck_ft_t(ck),.ck_ft_s(ck),.ft_ti_a(ft_ti_a),.ft_e_a(ft_e_a),.ft_s_a(ft_s_a),.ft_ti_b(x[1558:0]),.ft_e_b(x[1574:1559]),.ft_s_b(x[1608:1575])
`define KST_SC(x) .sc_d(x[31:0]),.sc_f(x[32]),.g_f(x[33])
  generate
    if(FORM==0)begin:g
      assign u_r=0;
      assign u_a=0;
      assign u_b=0;
      assign u_c=0;
      assign u_m=0;
      ot_qkh_head_native_r4_s_lk #(.Q_FP32(1)) ur(`KST_COM,`KST_SC(o_r));
      ot_qkh_head_native_r4_s_lk_kst #(.Q_FP32(1),.KT_ST(0)) ua(`KST_COM,`KST_SC(o_a));
      ot_qkh_head_native_r4_s_lk_kst #(.Q_FP32(1),.KT_ST(2)) ub(`KST_COM,`KST_SC(o_b));
      ot_qkh_head_native_r4_s_lk_kst #(.Q_FP32(1),.KT_ST(1)) uc(`KST_COM,`KST_SC(o_c));
      ot_qkh_head_native_r4_s_lk_kst #(.Q_FP32(1),.KT_ST(2),.KT_MUT(1)) um(`KST_COM,`KST_SC(o_m));
    end
    else if(FORM==1)begin:g
      assign u_r[2632:1609]=0;
      assign u_a[2632:1609]=0;
      assign u_b[2632:1609]=0;
      assign u_c[2632:1609]=0;
      assign u_m[2632:1609]=0;
      ot_qkh_head_native_r4_ft_s_lk #(.Q_FP32(1)) ur(`KST_COM,`KST_SC(o_r),`KST_FT(u_r));
      ot_qkh_head_native_r4_ft_s_lk_kst #(.Q_FP32(1),.KT_ST(0)) ua(`KST_COM,`KST_SC(o_a),`KST_FT(u_a));
      ot_qkh_head_native_r4_ft_s_lk_kst #(.Q_FP32(1),.KT_ST(2)) ub(`KST_COM,`KST_SC(o_b),`KST_FT(u_b));
      ot_qkh_head_native_r4_ft_s_lk_kst #(.Q_FP32(1),.KT_ST(1)) uc(`KST_COM,`KST_SC(o_c),`KST_FT(u_c));
      ot_qkh_head_native_r4_ft_s_lk_kst #(.Q_FP32(1),.KT_ST(2),.KT_MUT(1)) um(`KST_COM,`KST_SC(o_m),`KST_FT(u_m));
    end
    else if(FORM==2)begin:g
      assign u_r=0;
      assign u_a=0;
      assign u_b=0;
      assign u_c=0;
      assign u_m=0;
      ot_qkh_head_native_r4_s #(.Q_FP32(1)) ur(`KST_COM,`KST_SC(o_r));
      ot_qkh_head_native_r4_s_kst #(.Q_FP32(1),.KT_ST(0)) ua(`KST_COM,`KST_SC(o_a));
      ot_qkh_head_native_r4_s_kst #(.Q_FP32(1),.KT_ST(2)) ub(`KST_COM,`KST_SC(o_b));
      ot_qkh_head_native_r4_s_kst #(.Q_FP32(1),.KT_ST(1)) uc(`KST_COM,`KST_SC(o_c));
      ot_qkh_head_native_r4_s_kst #(.Q_FP32(1),.KT_ST(2),.KT_MUT(1)) um(`KST_COM,`KST_SC(o_m));
    end
    else if(FORM==3)begin:g
      assign u_r[2632:1609]=0;
      assign u_a[2632:1609]=0;
      assign u_b[2632:1609]=0;
      assign u_c[2632:1609]=0;
      assign u_m[2632:1609]=0;
      ot_qkh_head_native_r4_ft_s #(.Q_FP32(1)) ur(`KST_COM,`KST_SC(o_r),`KST_FT(u_r));
      ot_qkh_head_native_r4_ft_s_kst #(.Q_FP32(1),.KT_ST(0)) ua(`KST_COM,`KST_SC(o_a),`KST_FT(u_a));
      ot_qkh_head_native_r4_ft_s_kst #(.Q_FP32(1),.KT_ST(2)) ub(`KST_COM,`KST_SC(o_b),`KST_FT(u_b));
      ot_qkh_head_native_r4_ft_s_kst #(.Q_FP32(1),.KT_ST(1)) uc(`KST_COM,`KST_SC(o_c),`KST_FT(u_c));
      ot_qkh_head_native_r4_ft_s_kst #(.Q_FP32(1),.KT_ST(2),.KT_MUT(1)) um(`KST_COM,`KST_SC(o_m),`KST_FT(u_m));
    end
    else if(FORM==4)begin:g
      assign u_r[1608:0]=0;
      assign u_a[1608:0]=0;
      assign u_b[1608:0]=0;
      assign u_c[1608:0]=0;
      assign u_m[1608:0]=0;
      ot_qkh_head_native_r4 #(.Q_FP32(1)) ur(`KST_COM,`KST_SC(o_r),.ck_nb1({16{ck}}),.ck_nb2({16{ck}}),.nb_d(u_r[2632:1609]));
      ot_qkh_head_native_r4_kst #(.Q_FP32(1),.KT_ST(0)) ua(`KST_COM,`KST_SC(o_a),.ck_nb1({16{ck}}),.ck_nb2({16{ck}}),.nb_d(u_a[2632:1609]));
      ot_qkh_head_native_r4_kst #(.Q_FP32(1),.KT_ST(2)) ub(`KST_COM,`KST_SC(o_b),.ck_nb1({16{ck}}),.ck_nb2({16{ck}}),.nb_d(u_b[2632:1609]));
      ot_qkh_head_native_r4_kst #(.Q_FP32(1),.KT_ST(1)) uc(`KST_COM,`KST_SC(o_c),.ck_nb1({16{ck}}),.ck_nb2({16{ck}}),.nb_d(u_c[2632:1609]));
      ot_qkh_head_native_r4_kst #(.Q_FP32(1),.KT_ST(2),.KT_MUT(1)) um(`KST_COM,`KST_SC(o_m),.ck_nb1({16{ck}}),.ck_nb2({16{ck}}),.nb_d(u_m[2632:1609]));
    end
  endgenerate
  wire kv_r=g.ur.kpv_k[0];
  // the source head's score outputs, n edges back (h[0] = one edge back); the line runs through reset
  reg [33:0] h [0:7];
  integer shb=2,shc=1,chkm=0,rnd=0;
  wire [33:0] e_b=(shb==0)?o_r:h[shb-1];
  wire [33:0] e_c=(shc==0)?o_r:h[shc-1];
  wire [33:0] e_m=h[1];
  integer edges=0,mism_a=0,mism_b=0,mism_c=0,mism_m=0,mism_u=0,scores=0,flags=0,since=0,resets=0,armed=0,seed=11,seed0=11,t,b,w,i;
  integer trans_b=0,trans_c=0,trans_last=0;
  wire cmp_d=(armed!=0)||(rnd==0);
  wire in_tr=(since<=TRANS);          // reset transient of the unreset K-tree data path
  always @(negedge ck)begin
    if(rst_n)begin
      edges=edges+1;since=since+1;
      if(since>FLUSH)armed=1;
      // flags from the first edge out of reset; sc_d once the unreset data regs are flushed (RAND) or always (default init)
      if(o_a[33:32]!==o_r[33:32] || (cmp_d && o_a[31:0]!==o_r[31:0]))begin
        mism_a=mism_a+1;if(mism_a<4)$display("MISMATCH A edge=%0d since=%0d ref %h/%b vs kst0 %h/%b",edges,since,o_r[31:0],o_r[33:32],o_a[31:0],o_a[33:32]);end
      if(o_b[33:32]!==e_b[33:32] || (cmp_d && o_b[31:0]!==e_b[31:0] && !(in_tr && o_b[31:0]===o_r[31:0])))begin
        mism_b=mism_b+1;if(mism_b<4)$display("MISMATCH B edge=%0d since=%0d ref-%0d %h/%b vs kst2 %h/%b",edges,since,shb,e_b[31:0],e_b[33:32],o_b[31:0],o_b[33:32]);end
      else if(cmp_d && o_b[31:0]!==e_b[31:0])begin trans_b=trans_b+1;if(since>trans_last)trans_last=since;end
      if(o_c[33:32]!==e_c[33:32] || (cmp_d && o_c[31:0]!==e_c[31:0] && !(in_tr && o_c[31:0]===o_r[31:0])))begin
        mism_c=mism_c+1;if(mism_c<4)$display("MISMATCH C edge=%0d since=%0d ref-%0d %h/%b vs kst1 %h/%b",edges,since,shc,e_c[31:0],e_c[33:32],o_c[31:0],o_c[33:32]);end
      else if(cmp_d && o_c[31:0]!==e_c[31:0])begin trans_c=trans_c+1;if(since>trans_last)trans_last=since;end
      if(o_m[33:32]!==e_m[33:32] || (cmp_d && !in_tr && o_m[31:0]!==e_m[31:0]))mism_m=mism_m+1;
      if(cmp_d && (u_a!==u_r || u_b!==u_r || u_c!==u_r || u_m!==u_r))begin
        mism_u=mism_u+1;if(mism_u<4)$display("MISMATCH U edge=%0d (feed-through / node beat moved)",edges);end
      if(kv_r===1'b1)scores=scores+1;
      if(o_r[33:32]!=2'b00)flags=flags+1;
    end else since=0;
    for(i=7;i>0;i=i-1)h[i]=h[i-1];
    h[0]=o_r;
  end
  task automatic rst(input integer n);
    rst_n=0;c_in=0;q_valid_in=0;repeat(n)@(negedge ck);rst_n=1;resets=resets+1;repeat(12)@(negedge ck);
  endtask
  task automatic pass(input integer rows,input integer ltr,input integer bad,input integer rcut);
    // Q: 32 FP32 beats (head HD 128 x 4 heads x 32 b / 512), then K rows on every cycle; bad: rows with FP specials
    // (inf / nan exponents -> the lane fault path gf / sc_f); rcut > 0: reset 8 edges at row rcut, mid stream
    for(b=0;b<32;b=b+1)begin q_valid_in=1;q_beat_in=6'(b);for(w=0;w<16;w=w+1)q_data_in[32*w+:32]=32'h3c000000^$random(seed)&32'h807fffff;@(negedge ck);end
    q_valid_in=0;
    for(t=0;t<rows;t=t+1)begin
      c_in={1'b1,1'b0,t==0,1'b0};for(w=0;w<32;w=w+1)row_in[32*w+:32]=$random(seed);e_in=$random(seed);
      if(bad && (t%37)==5)row_in[32*(t%32)+:32]=32'h7f800000|($random(seed)&32'h807fffff);
      lt_in=ltr?12'($random(seed)):12'd0;ft_ti_a={49{$random(seed)}};ft_e_a=$random(seed);ft_s_a={$random(seed),2'($random(seed))};
      @(negedge ck);
      if(rcut>0 && t==rcut)begin rst_n=0;repeat(8)@(negedge ck);rst_n=1;resets=resets+1;end
    end
    c_in=0;repeat(80)begin lt_in=ltr?12'($random(seed)):12'd0;ft_ti_a={49{$random(seed)}};@(negedge ck);end
  endtask
  initial begin
    if($value$plusargs("SEED=%d",seed))begin end
    seed0=seed;
    if($value$plusargs("SHB=%d",shb))begin end
    if($value$plusargs("SHC=%d",shc))begin end
    if($value$plusargs("CHKM=%d",chkm))begin end
    if($value$plusargs("RAND=%d",rnd))begin end
    for(i=0;i<8;i=i+1)h[i]=0;
    repeat(6)@(negedge ck);rst_n=1;repeat(12)@(negedge ck);
    if(rnd!=0)repeat(FLUSH)@(negedge ck);
    pass(600,0,0,0);rst(8);pass(300,0,1,0);hid=2'd2;pass(400,FORM==4,0,0);
    rst(4);hid=2'd3;pass(300,0,1,137);hid=2'd0;pass(200,0,0,0);rst(8);pass(120,0,0,0);
    if(mism_a==0 && mism_b==0 && mism_c==0 && mism_u==0 && scores>0 && mism_m>0 && (chkm==0))
      $display("PASS qkh_head_kst form %0d: KT_ST 0 == source head; KT_ST 2 / 1 == source head %0d / %0d edges earlier; %0d edges, %0d score edges, %0d flag edges, %0d resets (reset-aligned sc_d transient edges %0d / %0d, last %0d after release); 14-lane mutant off the law on %0d edges; seed %0d rand %0d",
               FORM,shb,shc,edges,scores,flags,resets,trans_b,trans_c,trans_last,mism_m,seed0,rnd);
    else $display("FAIL qkh_head_kst form %0d shb %0d shc %0d chkm %0d: mism A %0d B %0d C %0d U %0d mutant %0d scores %0d seed %0d rand %0d",FORM,shb,shc,chkm,mism_a,mism_b,mism_c,mism_u,mism_m,scores,seed0,rnd);
    $finish;
  end
endmodule
